class Fixture(b165.Fixture):
    """The landed Block 165 fixture with a PLUGGABLE link coupling.

    The committed wiring is gx = i s_x, gt = i s_t.  T3 needs gt to range over
    the whole complex coupling space, so the healed edge differentials are
    rebuilt here for an arbitrary (gx, gt) -- by exactly the committed
    construction, which gate B pins by requiring the pluggable constructor at the
    committed coupling to reproduce the landed edge differentials entry for
    entry.
    """

    def connection_for(self, gx, gt) -> dict:
        local = gx * EX + gt * ET
        rt, rx = b105.shift_lifts()
        local_d: dict = {}
        for origin in ORIGINS:
            gauge = (rt ** origin[0]) * (rx ** origin[1])
            block = sp.expand(gauge.H * local * gauge)
            out: dict = {}
            for anchor in self.chart_cells(origin):
                sites = self.cell_sites(*anchor)
                for p in range(4):
                    for q in range(4):
                        if block[p, q] != 0:
                            key = (sites[p], sites[q])
                            out[key] = out.get(key, 0) + block[p, q]
            local_d[origin] = sclean(out)
        star = sadd(local_d[(0, 0)], sscale(local_d[(1, 0)], -1))
        return {
            (CHART_INDEX[a], CHART_INDEX[b]): sadd(
                local_d[a],
                sscale(
                    star,
                    HEALING_WEIGHTS[CHART_INDEX[b]]
                    - HEALING_WEIGHTS[CHART_INDEX[a]],
                ),
            )
            for a in ORIGINS
            for b in ORIGINS
        }


def ssubs(matrix: dict, mapping: dict) -> dict:
    return sclean({
        key: sp.expand(value.subs(mapping)) if hasattr(value, "subs") else value
        for key, value in matrix.items()
    })


def region_pin(fx: Fixture, links) -> dict:
    """sigma = 0 on the given time links: b -> 0 and a -> nu."""
    pin: dict = {}
    for slot in links:
        slot = slot % fx.PHYS_T
        for x in range(fx.LX):
            pin[fx.B[(slot, x)]] = sp.Integer(0)
            pin[fx.A[(slot, x)]] = fx.NU[(slot, x)]
    return pin


def hodge_trace_D(fx: Fixture) -> dict:
    return {
        (t, x): (
            fx.NU[(t, x)]
            + fx.A[((t - 1) % fx.PHYS_T, x)]
            + fx.A[(t, (x - 1) % fx.LX)]
            + fx.MU[((t - 1) % fx.PHYS_T, (x - 1) % fx.LX)]
        ) / 4
        for (t, x) in fx.CELLS
    }


def free_shears(fx: Fixture, c: int) -> tuple:
    """The shear moduli the region at slice c leaves FREE -- the record."""
    pinned = {(c - 1) % fx.PHYS_T, c % fx.PHYS_T}
    return tuple(fx.B[k] for k in fx.CELLS if k[0] not in pinned)


def graded_carrier(fx: Fixture, c: int, sigma) -> dict:
    """A cone-admissible CURVED carrier interior to the region at slice c."""
    pinned = {(c - 1) % fx.PHYS_T, c % fx.PHYS_T}
    return {
        (t, x): (
            sp.Integer(0) if t in pinned else sp.sympify(sigma),
            R(1 + (3 * t + 5 * x) % 5, 3) + R(1, 2),
        )
        for (t, x) in fx.CELLS
    }


def carrier_substitution(fx: Fixture, field: dict) -> dict:
    nu, a, b, mu = fx.moduli_from_field(field)
    out: dict = {}
    for key in fx.CELLS:
        out[fx.NU[key]] = nu[key]
        out[fx.A[key]] = a[key]
        out[fx.B[key]] = b[key]
        out[fx.MU[key]] = mu[key]
    return out


def region_pairing(fx: Fixture, c: int, edge_d: dict, pinned_links, mass=MASS):
    """[r Q]_{S,S} at the x-trivial reflection fixing slice c, on the region."""
    label = next(l for l in fx.x_trivial if fx.fixed_slice(l) == c)
    pin = region_pin(fx, pinned_links)
    hodge = ssubs(fx.H_free, pin)
    action = fx.quotient_action(edge_d, hodge, mass)
    return fx.pairing(fx.descent(label), action, fx.slice_rows(c, c + 1)), pin


