SWEEP_ST = (sp.Integer(0), R(1, 16), R(1, 8), R(1, 4), R(1, 2), R(3, 4),
            -R(1, 8), -R(1, 2))
SWEEP_NONZERO = len(SWEEP_THETAS) * (len(SWEEP_ST) - 1)          # 35
GENERATORS_EXERCISED = 1                       # ET, and only ET

# T4a: the margin law
MARGIN_CONSTANT = R(57, 160)                   # m . kappa_2, constant
KAPPA2_MASSES = (R(1, 3), sp.Integer(1), sp.Integer(3), sp.Integer(7))
KAPPA2_SIGMAS = (R(1, 5), R(2, 5), R(3, 5))
FROBENIUS_E = {R(1, 5): R(4225, 165888), R(2, 5): R(4225, 31752),
               R(3, 5): R(4225, 8192)}
E_LIVE = {"8x4": (2, 4), "12x4": (0, 6), "8x6": (2, 4)}
PROBE_ST = R(1, 2)

# T4b: the exact census, which REPLACES the solve's float search entirely
THETA_LABEL = (-1, 7, -1, 0)                   # ODD p_t -- a LINK reflection
CENSUS_MASSES = (R(1, 3), sp.Integer(2), -sp.Integer(1))
CENSUS_ST = (R(1, 5), R(4, 5), -R(1, 2))
CENSUS_CELLS = 3456
CENSUS_JOINT = 0
WALL_CELLS = 1152
WALL_JOINT = 0
WALL_VACUOUS = 32
WALL_SIGNATURE = ((4, 0, 4), (0, 0, 8))        # (n_+, n_-, n_0), THIS note

