@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    convention: tuple        # B: the banner, and the rebuild anchor
    freezing: tuple          # C: T1
    composite: tuple         # D: T2
    coupling: tuple          # E: T3
    margin: tuple            # F: T4a and T4b
    record: tuple            # G: T5
    shape: tuple             # H: the growth law
    deep: bool
    exact_no_float: bool
    scope: dict


# ---------------------------------------------------------------------------
# B. THE CONVENTION COLLISION, measured on identical matrices
# ---------------------------------------------------------------------------
def convention_probe() -> tuple:
    """The two LANDED helpers, called on the same three matrices.

    b163/b164's congruence_inertia returns (n_+, n_0, n_-); Block 165's
    real_symmetric_inertia returns (n_+, n_-, n_0).  Both are correct and both
    agree the region normal form is PSD; the PRINTED STRING is what collides.
    """
    region_form = sp.diag(*([1] * 4 + [0] * 4))
    split_form = sp.diag(*([1] * 4 + [-1] * 4))
    zero_form = sp.zeros(8, 8)
    pairs = tuple(
        (tuple(b163.guarded_inertia(m)), tuple(inertia(m)))
        for m in (region_form, split_form, zero_form)
    )
    landed_psd = b163.is_psd(b163.guarded_inertia(region_form))
    here_psd = inertia(region_form)[1] == 0 and inertia(region_form)[0] == 4
    orders_differ = any(landed != here for landed, here in pairs)
    return pairs, landed_psd, here_psd, orders_differ


# ---------------------------------------------------------------------------
# C. T1 -- THE INTER-SLICE MAP, on BOTH the metric and the action
# ---------------------------------------------------------------------------
def freezing_probe(fx: Fixture) -> dict:
    """W = 0 on the region, measured on the HODGE and on the ACTION.

    The solve measured the quotiented cover HODGE and drew a DYNAMICAL
    conclusion.  The independent checker measured the ACTION's +1-displacement
    block, which is the object the conclusion needs.  Both are measured here and
    both are reported; the note credits the action measurement to the checker.
    """
    n = fx.LX
    out: dict = {}
    hq = dense(fx.quotient(fx.H_free), fx.PHYS, fx.PHYS)
    out["displacements"] = tuple(sorted(
        {(j // fx.LX - i // fx.LX) % fx.PHYS_T for (i, j) in fx.quotient(fx.H_free)}
    ))
    out["distance_two_absent"] = 2 not in out["displacements"]

    action_zero = hodge_zero = slices = 0
    action_symbols: set = set()
    normal_form = True
    for c in range(fx.PHYS_T):
        pin = region_pin(fx, [c - 1, c, c + 1])
        hodge = ssubs(fx.H_free, pin)
        action = ssubs(fx.quotient_action(fx.edge_d[(0, 0)], hodge, MASS),
                       {ST: 0})
        block_a = sp.expand(
            dense(action, fx.PHYS, fx.PHYS)[fx.slice_rows(c + 1), fx.slice_rows(c)]
        )
        block_h = sp.expand(hq.subs(pin)[fx.slice_rows(c + 1), fx.slice_rows(c)])
        slices += 1
        action_zero += int(block_a == sp.zeros(n, n))
        hodge_zero += int(block_h == sp.zeros(n, n))
        action_symbols |= free_symbols_of(block_a)
        # ker P_c is EXACTLY the slice-(c+1) block, so dim H_c = L_x
        pairing, _ = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
        want = sp.zeros(2 * n, 2 * n)
        trace_d = hodge_trace_D(fx)
        for x in range(n):
            want[x, x] = MASS * sp.expand(trace_d[(c, x)].subs(pin))
        if sp.expand(pairing.subs({ST: 0}) - want) != sp.zeros(2 * n, 2 * n):
            normal_form = False
    out["action_zero"] = (action_zero, slices)
    out["hodge_zero"] = (hodge_zero, slices)
    out["action_symbols_empty"] = not action_symbols
    out["normal_form"] = normal_form
    out["dim_Hc"] = n
    out["prediction_dim"] = 2 * n
    out["prediction_satisfiable"] = 2 * n <= n

    # MECHANISM: H_q[c+1, c] is a form in the shear moduli of link c ALONE
    carried = {}
    for c in range(fx.PHYS_T):
        symbols: set = set()
        for x in range(n):
            for y in range(n):
                symbols |= sp.expand(
                    hq[fx.slice_rows(c + 1)[x], fx.slice_rows(c)[y]]
                ).free_symbols
        carried[c] = tuple(sorted(
            {t for (t, x) in fx.CELLS if fx.B[(t, x)] in symbols}
        ))
    out["carried_by_link_c"] = all(carried[c] == (c,) for c in range(fx.PHYS_T))

    # CONTROL: switch link c's shear back ON and the same block is full rank
    c = SLICE_C
    pin_off = region_pin(fx, [c - 1])
    substitution = carrier_substitution(fx, {
        (t, x): (sp.Integer(0) if t == (c - 1) % fx.PHYS_T else R(2, 5),
                 R(1 + (3 * t + 5 * x) % 5, 3) + R(1, 2))
        for (t, x) in fx.CELLS
    })
    control = sp.expand(
        hq.subs(pin_off)[fx.slice_rows(c + 1), fx.slice_rows(c)].subs(substitution)
    )
    trace_d = hodge_trace_D(fx)
    g_c = sp.diag(*[sp.expand(trace_d[(c, x)].subs(pin_off).subs(substitution))
                    for x in range(n)])
    g_c1 = sp.diag(*[
        sp.expand(trace_d[((c + 1) % fx.PHYS_T, x)].subs(pin_off).subs(substitution))
        for x in range(n)])
    out["control_rank"] = control.rank()
    out["control_trace"] = sp.expand(sp.trace(g_c.inv() * control.H * g_c1 * control))
    return out


# ---------------------------------------------------------------------------
# D. T2 -- THE DOUBLED-STEP COMPOSITE, on C alone AND on the full object
# ---------------------------------------------------------------------------
def composite_probe(fx: Fixture) -> dict:
    n = fx.LX
    c = SLICE_C
    out: dict = {}
    pairing, _ = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
    off = sp.expand(pairing[:n, n:])
    c1 = sp.expand(sp.diff(off, ST))
    out["c_vanishes_at_zero"] = sp.expand(off.subs({ST: 0})) == sp.zeros(n, n)
    out["c_is_odd"] = sp.expand(off - ST * c1) == sp.zeros(n, n)
    out["c1_nonzero"] = c1 != sp.zeros(n, n)
    out["rank_c1"] = c1.rank()
    twisted = sp.expand(off.subs({ST: -ST}).H * off)
    out["m_even"] = sp.expand(twisted.subs({ST: -ST}) - twisted) == sp.zeros(n, n)
    out["m_hermitian"] = sp.expand(twisted - twisted.H) == sp.zeros(n, n)
    out["m_identity"] = (
        sp.expand(twisted + ST ** 2 * (c1.H * c1)) == sp.zeros(n, n)
    )
    out["m_zero_at_zero"] = sp.expand(twisted.subs({ST: 0})) == sp.zeros(n, n)

    # THE CHECKER'S ATTACK: the composite on the FULL adjacent-slice object
    twist = sp.expand(pairing.subs({ST: -ST}))
    full = sp.expand((twist * pairing + (twist * pairing).H) / 2)
    out["full_hermitian"] = (
        sp.expand(full - full.H) == sp.zeros(2 * n, 2 * n)
    )
    out["full_corner_is_minus_ctc"] = (
        sp.expand(full[n:, n:] + off.H * off) == sp.zeros(n, n)
    )

    substitution = carrier_substitution(fx, graded_carrier(fx, c, R(2, 5)))
    substitution[SX] = R(3, 5)
    substitution[MASS] = sp.Integer(1)
    out["m_inertia"] = tuple(inertia(
        sp.expand(twisted.subs(substitution).subs({ST: PROBE_ST}))
    ))
    out["full_inertia"] = tuple(
        tuple(inertia(sp.expand(full.subs(substitution).subs({ST: value}))))
        for value in (PROBE_ST, -R(1, 4))
    )
    sweep = tuple(
        tuple(inertia(sp.expand(twisted.subs(substitution).subs({ST: value}))))
        for value in (R(1, 8), -R(1, 8), R(1, 4), -R(1, 4), R(1, 2), -R(1, 2),
                      R(3, 2))
    )
    out["sweep_points"] = len(sweep)
    out["sweep_psd"] = sum(1 for tri in sweep if tri[1] == 0 and tri[0] > 0)

    # CONTROL: off the region evenness FAILS -- it is C's oddness, not a general
    # identity of the construction
    off_region, _ = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1])
    off_c = sp.expand(off_region[:n, n:])
    off_twist = sp.expand(off_c.subs({ST: -ST}).H * off_c)
    out["off_region_even"] = (
        sp.expand(off_twist.subs({ST: -ST}) - off_twist) == sp.zeros(n, n)
    )
    return out


# ---------------------------------------------------------------------------
# E. T3 -- THE COUPLING-CLASS THEOREM (the checker's, credited)
# ---------------------------------------------------------------------------
G_RE, G_IM = sp.symbols("g_re g_im", real=True)


def cayley(theta, s):
    """The solve's interpolation from the additive to the Cayley wiring."""
    return I * s / (1 - theta * I * s / 2)


def coupling_probe(fx: Fixture, edges: tuple) -> dict:
    """C(g_t) = g_t C1 EXACTLY, with B and the corner g_t-free.

    A FREE complex coupling, not a family: the sweep is a curve in the space
    this one measurement covers whole.  Symbolic carrier, symbolic m, symbolic
    s_x.
    """
    n = fx.LX
    c = SLICE_C
    out: dict = {}
    coupling = G_RE + I * G_IM
    edge_d = fx.connection_for(I * SX, coupling)
    label = next(l for l in fx.x_trivial if fx.fixed_slice(l) == c)
    hodge = ssubs(fx.H_free, region_pin(fx, [c - 1, c]))
    holomorphic = factorises = c1_free = b_free = corner_free = 0
    corner_hollow = 0
    coefficient = None
    for key in edges:
        action = fx.quotient_action(edge_d[key], hodge, MASS)
        pairing = fx.pairing(fx.descent(label), action, fx.slice_rows(c, c + 1))
        off = sp.expand(pairing[:n, n:])
        mass_block = sp.expand(pairing[:n, :n])
        corner = sp.expand(pairing[n:, n:])
        d_re = sp.expand(sp.diff(off, G_RE))
        d_im = sp.expand(sp.diff(off, G_IM))
        holomorphic += int(sp.expand(d_im - I * d_re) == sp.zeros(n, n))
        factorises += int(sp.expand(off - coupling * d_re) == sp.zeros(n, n))
        c1_free += int(not (free_symbols_of(d_re) & {G_RE, G_IM}))
        b_free += int(not (free_symbols_of(mass_block) & {G_RE, G_IM}))
        corner_free += int(not (free_symbols_of(corner) & {G_RE, G_IM}))
        corner_hollow += int(corner == sp.zeros(n, n))
        if key == fx.EDGE_KEYS[0]:
            substitution = carrier_substitution(fx, graded_carrier(fx, c, R(2, 5)))
            coefficient = sp.expand(d_re[0, 0].subs(substitution))
    out["edges"] = len(edges)
    out["holomorphic"] = holomorphic
    out["factorises"] = factorises
    out["c1_g_free"] = c1_free
    out["b_g_free"] = b_free
    out["corner_g_free"] = corner_free
    out["corner_hollow"] = corner_hollow
    out["coefficient"] = coefficient
    return out


def wiring_probe(fx: Fixture) -> dict:
    """The sweep (corroboration only) and the two struck structural claims."""
    n = fx.LX
    c = SLICE_C
    out: dict = {}
    label = next(l for l in fx.x_trivial if fx.fixed_slice(l) == c)
    nu, a, b, mu = fx.moduli_from_field(graded_carrier(fx, c, R(2, 5)))
    hodge = fx.cover_hodge(nu, a, b, mu)
    psd_at_zero = zero_points = nonzero_points = psd_at_nonzero = 0
    inertias: set = set()
    for theta in SWEEP_THETAS:
        for value in SWEEP_ST:
            edge_d = fx.connection_for(I * R(3, 5), cayley(theta, value))
            action = fx.quotient_action(edge_d[(0, 0)], hodge, sp.Integer(1))
            triple = tuple(inertia(
                fx.pairing(fx.descent(label), action, fx.slice_rows(c, c + 1))
            ))
            inertias.add((value == 0, triple))
            if value == 0:
                zero_points += 1
                psd_at_zero += int(triple[1] == 0 and triple[0] == n)
            else:
                nonzero_points += 1
                psd_at_nonzero += int(triple[1] == 0 and triple[0] > 0)
    out["sweep"] = (psd_at_zero, zero_points, psd_at_nonzero, nonzero_points)
    out["sweep_inertias"] = tuple(sorted(inertias))
    # the pairing at s_t = 0 is LITERALLY theta-independent
    base = None
    theta_free = True
    for theta in SWEEP_THETAS:
        edge_d = fx.connection_for(I * R(3, 5), cayley(theta, sp.Integer(0)))
        action = fx.quotient_action(edge_d[(0, 0)], hodge, sp.Integer(1))
        pairing = fx.pairing(fx.descent(label), action, fx.slice_rows(c, c + 1))
        if base is None:
            base = pairing
        elif sp.expand(pairing - base) != sp.zeros(2 * n, 2 * n):
            theta_free = False
    out["calibration_theta_free"] = theta_free
    # ET IS NILPOTENT, so the group/algebra distinction is VACUOUS
    out["et_nilpotent"] = sp.expand(ET * ET) == sp.zeros(4, 4)
    out["exp_is_additive"] = all(
        sp.expand(sp.exp(I * s * ET) - (sp.eye(4) + I * s * ET)) == sp.zeros(4, 4)
        for s in (R(1, 2), R(3, 4))
    )
    # THE "UNIMODULAR LINK" CLAIM, tested on the MATRIX and on the SCALAR
    out["link_unitary"] = tuple(
        sp.expand((sp.eye(4) + cayley(1, s) * ET)
                  * (sp.eye(4) + cayley(1, s) * ET).H) == sp.eye(4)
        for s in (R(1, 2), R(3, 4))
    )
    out["scalar_modulus_one"] = tuple(
        sp.simplify(sp.Abs(1 + cayley(1, s)) - 1) == 0
        for s in (R(1, 2), R(3, 4))
    )
    # exactly ONE temporal generator was exercised, and that is the open scope
    out["generators_exercised"] = len({sp.srepr(sp.Matrix(ET))})
    return out


# ---------------------------------------------------------------------------
# F. T4a -- THE MARGIN LAW, exactly and with NO FLOAT
# ---------------------------------------------------------------------------
def margin_probe(fx: Fixture, edges: tuple) -> dict:
    n = fx.LX
    out: dict = {}
    # a = 0 IDENTICALLY: the region Gram at s_t = 0 has rank L_x of 2 L_x
    ranks: set = set()
    for lab in fx.x_trivial:
        c = fx.fixed_slice(lab)
        pairing, _ = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
        ranks.add(sp.expand(pairing.subs({ST: 0})).rank())
    out["gram_rank"] = tuple(sorted(ranks))
    out["ambient_rank"] = 2 * n

    # E lives on the ODD fixed slices at T_phys = 4 and NOWHERE at T_phys >= 6
    live = cells = 0
    for key in edges:
        for lab in fx.x_trivial:
            c = fx.fixed_slice(lab)
            pairing, _ = region_pairing(fx, c, fx.edge_d[key], [c - 1, c])
            corner_derivative = sp.expand(sp.diff(pairing[n:, n:], ST))
            cells += 1
            live += int(corner_derivative != sp.zeros(n, n))
    out["e_live"] = (live, cells)
    out["e_live_per_edge"] = (live // len(edges), cells // len(edges))
    return out


def kappa_probe(fx: Fixture) -> dict:
    """kappa_2 = lambda_max(C1* B^-1 C1), exactly and with NO FLOAT.

    The maximum eigenvalue is certified WITHOUT a numerical eigenvalue routine:
    m . C1* B^-1 C1 is measured to be constant in m, and the certificate is
    that (m Sch - MARGIN_CONSTANT . 1) has ZERO positive directions and zero
    determinant -- exact inertia and an exact determinant, no floats.
    """
    n = fx.LX
    c = SLICE_C
    out: dict = {}
    pairing, _ = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
    corner_derivative = sp.expand(sp.diff(pairing[n:, n:], ST))
    c1 = sp.expand(sp.diff(pairing[:n, n:], ST))
    mass_block = sp.expand(pairing[:n, :n].subs({ST: 0}))
    out["e_zero_diagonal"] = all(
        corner_derivative[x, x] == 0 for x in range(n)
    )
    out["e_symbols"] = tuple(sorted(
        str(s) for s in free_symbols_of(corner_derivative)
    ))
    out["e_in_free_shears_only"] = (
        free_symbols_of(corner_derivative) <= set(free_shears(fx, c)) | {SX}
    )
    out["e_m_free"] = MASS not in free_symbols_of(corner_derivative)
    out["c1_m_free"] = MASS not in free_symbols_of(c1)

    frobenius = {}
    constant_across_mass = True
    lam_max_certified = True
    is_scalar = True
    values: set = set()
    for sigma in KAPPA2_SIGMAS:
        substitution = carrier_substitution(fx, graded_carrier(fx, c, sigma))
        substitution[SX] = R(3, 5)
        e_numeric = sp.expand(corner_derivative.subs(substitution))
        frobenius[sigma] = sp.expand(
            sum(sp.expand(entry * sp.conjugate(entry)) for entry in e_numeric)
        )
        c1_numeric = sp.expand(c1.subs(substitution))
        reference = None
        for mass in KAPPA2_MASSES:
            schur = sp.expand(mass * (
                c1_numeric.H
                * sp.expand(mass_block.subs(substitution).subs({MASS: mass})).inv()
                * c1_numeric
            ))
            if reference is None:
                reference = schur
            elif sp.expand(schur - reference) != sp.zeros(n, n):
                constant_across_mass = False
        # the eigenvalue is READ OFF the measurement, not compared to a literal:
        # m . C1* B^-1 C1 is measured to be a SCALAR matrix, and the scalar is
        # then certified as the maximum by an exact inertia and an exact
        # determinant.  No numerical eigenvalue routine and no float.
        value = sp.expand(reference[0, 0])
        values.add(value)
        if sp.expand(reference - value * sp.eye(n)) != sp.zeros(n, n):
            is_scalar = False
        shifted = sp.expand(reference - value * sp.eye(n))
        if not (tuple(inertia(shifted))[0] == 0 and sp.expand(shifted.det()) == 0):
            lam_max_certified = False
    out["frobenius"] = tuple((sigma, frobenius[sigma]) for sigma in KAPPA2_SIGMAS)
    out["m_kappa2_constant"] = constant_across_mass
    out["m_kappa2_is_scalar"] = is_scalar
    out["m_kappa2_value"] = values.pop() if len(values) == 1 else None
    out["lam_max_certified"] = lam_max_certified
    out["kappa2_by_mass"] = tuple(
        (mass, sp.nsimplify(out["m_kappa2_value"] / mass))
        for mass in KAPPA2_MASSES
    ) if out["m_kappa2_value"] is not None else ()
    # kappa is LINEAR in sigma: ||E||_F^2 is exactly proportional to b^2
    shear_modulus = {s: sp.expand(s / (1 - s ** 2)) for s in KAPPA2_SIGMAS}
    first = KAPPA2_SIGMAS[0]
    out["kappa_linear_in_sigma"] = all(
        sp.expand(frobenius[s] * shear_modulus[first] ** 2
                  - frobenius[first] * shear_modulus[s] ** 2) == 0
        for s in KAPPA2_SIGMAS
    )
    return out


def mass_inertia_probe(fx: Fixture) -> dict:
    """NO MASS MAKES THE REGION POSITIVE.

    "The margin improves with mass" is a statement about a NORMALISED depth, not
    about positivity: at every finite m > 0 and every s_t != 0 the pairing has
    NEGATIVE directions.  Measured at four masses rather than argued.
    """
    c = SLICE_C
    pairing, _ = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
    substitution = carrier_substitution(fx, graded_carrier(fx, c, R(2, 5)))
    substitution[SX] = R(3, 5)
    triples = tuple(
        (mass, tuple(inertia(sp.expand(
            pairing.subs(substitution).subs({MASS: mass, ST: PROBE_ST})
        ))))
        for mass in KAPPA2_MASSES
    )
    return {
        "inertia_by_mass": triples,
        "never_psd": all(triple[1] > 0 for _mass, triple in triples),
        "masses": len(triples),
    }


# ---------------------------------------------------------------------------
# F. T4b -- THE TWO-CONE CENSUS.  This REPLACES the solve's float search.
# ---------------------------------------------------------------------------
CENSUS_SHEARS = (
    ("flat", lambda t, x: 0),
    ("uniform", lambda t, x: R(2, 5)),
    ("far only", lambda t, x: R(1, 2) if t in (2, 3) else 0),
    ("alternating", lambda t, x: R(1, 3) * (-1) ** (t + x)),
)
CENSUS_VOLUMES = (
    ("nu=1", lambda t, x: 1),
    ("nu graded", lambda t, x: R(1 + (t + x) % 3, 2)),
)


def census_fields(fx: Fixture) -> tuple:
    return tuple(
        (f"{sname} / {vname}",
         sname == "flat",
         {(t, x): (sp.sympify(shear(t, x)), sp.sympify(volume(t, x)))
          for (t, x) in fx.CELLS})
        for sname, shear in CENSUS_SHEARS
        for vname, volume in CENSUS_VOLUMES
    )


def two_cone_census(fx: Fixture, edges: tuple, masses: tuple,
                    st_values: tuple) -> dict:
    """JOINT FEASIBLE requires BOTH cones satisfied NON-VACUOUSLY.

    A form that vanishes identically is PSD only degenerately and is NOT a cone
    point.  The rider `rank > 0 on both sides` is what makes the predicate
    usable; without it Block 160's mass-blindness manufactures false positives.
    """
    cells = joint = vacuous = 0
    signatures: set = set()
    flat_hits = 0
    all_x_trivial = True
    for _name, is_flat, field in census_fields(fx):
        hodge = fx.cover_hodge(*fx.moduli_from_field(field))
        for key in edges:
            for mass in masses:
                for value in st_values:
                    action = ssubs(
                        fx.quotient_action(fx.edge_d[key], hodge, mass),
                        {SX: R(3, 5), ST: value},
                    )
                    exchange = tuple(inertia(fx.pairing(
                        fx.descent(THETA_LABEL), action, fx.slice_rows(0, 1)
                    )))
                    for label in fx.involutive:
                        c = fx.fixed_slice(label)
                        site = tuple(inertia(fx.pairing(
                            fx.descent(label), action, fx.slice_rows(c, c + 1)
                        )))
                        cells += 1
                        clean = site[1] == 0 and exchange[1] == 0
                        if clean and site[0] > 0 and exchange[0] > 0:
                            joint += 1
                        if clean and (site[0] > 0 or exchange[0] > 0):
                            vacuous += 1
                            signatures.add((site, exchange))
                            flat_hits += int(is_flat)
                            if not (label[2] == 1 and label[3] == 0):
                                all_x_trivial = False
    return {
        "cells": cells,
        "joint": joint,
        "vacuous": vacuous,
        "signatures": tuple(sorted(signatures)),
        "vacuous_all_flat": vacuous == flat_hits,
        "vacuous_all_x_trivial": all_x_trivial,
        "expected_vacuous": (
            sum(1 for _n, is_flat, _f in census_fields(fx) if is_flat)
            * len(edges)
            * sum(1 for mass in masses if mass > 0)
            * len(fx.x_trivial)
        ),
    }


def exchange_label_probe(fx: Fixture) -> dict:
    """The exchange label is a LINK reflection, not a site one."""
    return {
        "odd_pt": THETA_LABEL[1] % 2 == 1,
        "in_site_labels": THETA_LABEL in fx.site_labels,
        "in_link_labels": THETA_LABEL in fx.link_labels,
        "in_involutive": THETA_LABEL in fx.involutive,
    }


# ---------------------------------------------------------------------------
# G. T5 -- THE RECORD, at PRECISE QUANTIFIER SCOPE
# ---------------------------------------------------------------------------
def record_probe(fx: Fixture) -> dict:
    n = fx.LX
    c = SLICE_C
    out: dict = {}
    pairing, pin = region_pairing(fx, c, fx.edge_d[(0, 0)], [c - 1, c])
    flat_pairing = sp.expand(pairing.subs({ST: 0}))
    record = free_shears(fx, c)

    # (a) NO representative in the PAIRING's induced algebra
    out["dp_db_zero"] = all(
        sp.expand(sp.diff(flat_pairing, modulus)) == sp.zeros(2 * n, 2 * n)
        for modulus in record
    )
    out["gram_shear_symbols"] = tuple(sorted(
        str(s) for s in (set(fx.SHEARS) & free_symbols_of(flat_pairing))
    ))
    flip = {fx.B[k]: -fx.B[k] for k in fx.CELLS}
    out["flip_identity"] = (
        sp.expand(flat_pairing.subs(flip) - flat_pairing) == sp.zeros(2 * n, 2 * n)
    )
    signature = sp.diag(sp.eye(n), -sp.eye(n))
    out["flip_only_congruence"] = (
        sp.expand(pairing.subs(flip) - signature * pairing * signature)
        != sp.zeros(2 * n, 2 * n)
    )

    # (b) BUT LIVE IN THE FULL ACTION -- the checker's scope correction
    action = ssubs(
        fx.quotient_action(fx.edge_d[(0, 0)], ssubs(fx.H_free, pin), MASS),
        {ST: 0},
    )
    action_symbols = free_symbols_of(dense(action, fx.PHYS, fx.PHYS))
    out["record_live_in_action"] = (
        len([m for m in record if m in action_symbols]), len(record)
    )

    # (c) THE RETRACTED TRADE: where is the record visible in the PAIRING at all?
    pairing_symbols = free_symbols_of(pairing)
    visible = tuple(m for m in record if m in pairing_symbols)
    corner_symbols = free_symbols_of(sp.expand(pairing[n:, n:]))
    outside = free_symbols_of(sp.expand(pairing[:n, :]))
    out["record_visible"] = (len(visible), len(record))
    out["visible_in_corner"] = len([m for m in visible if m in corner_symbols])
    out["visible_outside_corner"] = len([m for m in visible if m in outside])
    out["corner_vanishes"] = sp.expand(pairing[n:, n:]) == sp.zeros(n, n)

    # (d) the induced state is CLASSICAL, exactly
    trace_d = hodge_trace_D(fx)
    flat = carrier_substitution(fx, {
        (t, x): (sp.Integer(0), sp.Integer(1)) for (t, x) in fx.CELLS
    })
    weights = [sp.expand(trace_d[(c, x)].subs(pin).subs(flat)) for x in range(n)]
    total = sp.expand(sum(weights))
    out["induced_state"] = tuple(sp.expand(w / total) for w in weights)
    out["induced_state_sums_to_one"] = sp.expand(sum(out["induced_state"])) == 1
    out["record_factor_dim"] = 1 if out["dp_db_zero"] else n
    return out


# ---------------------------------------------------------------------------
# H. the shape: Block 165's growth law, re-derived from the pinning set
# ---------------------------------------------------------------------------
def shape_probe(fx: Fixture) -> dict:
    """The region is an OPEN, GROWING locus -- not a point.

    The ambient cone is TWO coordinates (nu, sigma) per cell; the region pins
    exactly the sigma coordinates of the two links incident to the fixed slice,
    ENUMERATED from the region's own definition.
    """
    ambient = 2 * len(fx.CELLS)
    pinned = len({(SLICE_C - 1) % fx.PHYS_T, SLICE_C % fx.PHYS_T}) * fx.LX
    return {
        "ambient": ambient,
        "codimension": pinned,
        "region_dim": ambient - pinned,
        "law": 2 * fx.LX * (fx.PHYS_T - 1),
    }


# ---------------------------------------------------------------------------
# measured facts (computed once, before any mutation flag is consulted)
# ---------------------------------------------------------------------------
def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    fixtures = {tag: Fixture(cover_t, lx, tag)
                for tag, cover_t, lx in FIXTURE_SPECS}
    control = fixtures["8x4"]

    # ---------------------------------------------------------------- B ----
    # the rebuild anchor: the PLUGGABLE constructor at the committed coupling
    # reproduces the landed edge differentials entry for entry, at every size
    anchor = tuple(
        all(
            sclean(sadd(
                fixtures[tag].connection_for(I * SX, I * ST)[key],
                sscale(fixtures[tag].edge_d[key], -1),
            )) == {}
            for key in fixtures[tag].EDGE_KEYS
        )
        for tag in TAGS
    )
    pairs, landed_psd, here_psd, orders_differ = convention_probe()
    convention = (
        pairs, landed_psd, here_psd, orders_differ, anchor,
        tuple(len(fixtures[tag].involutive) for tag in TAGS),
        tuple(len(fixtures[tag].x_trivial) for tag in TAGS),
    )

    # ---------------------------------------------------------------- C ----
    freezing = {tag: freezing_probe(fixtures[tag]) for tag in TAGS}

    # ---------------------------------------------------------------- D ----
    composite = {tag: composite_probe(fixtures[tag]) for tag in TAGS[:2]}

    # ---------------------------------------------------------------- E ----
    edges = {
        tag: (fixtures[tag].EDGE_KEYS if deep
              else fixtures[tag].EDGE_KEYS[:BASELINE_EDGES])
        for tag in TAGS
    }
    coupling = {tag: coupling_probe(fixtures[tag], edges[tag]) for tag in TAGS}
    wiring = wiring_probe(fixtures["12x4"])

    # ---------------------------------------------------------------- F ----
    margin = {tag: margin_probe(fixtures[tag], edges[tag]) for tag in TAGS}
    kappa = kappa_probe(control)
    census = two_cone_census(control, control.EDGE_KEYS[:1] + (control.EDGE_KEYS[11],),
                             CENSUS_MASSES, CENSUS_ST)
    wall = two_cone_census(control, control.EDGE_KEYS[:1] + (control.EDGE_KEYS[11],),
                           CENSUS_MASSES, (sp.Integer(0),))
    exchange = exchange_label_probe(control)
    mass_inertia = {tag: mass_inertia_probe(fixtures[tag]) for tag in TAGS[:2]}

    # ---------------------------------------------------------------- G ----
    record = {tag: record_probe(fixtures[tag]) for tag in TAGS}

    # ---------------------------------------------------------------- H ----
    shape = tuple(shape_probe(fixtures[tag]) for tag in TAGS)

    # exactness: every measured scalar, gated
    scalars: list = (
        [freezing[tag]["control_trace"] for tag in TAGS]
        + [value for _sigma, value in kappa["frobenius"]]
        + [value for _mass, value in kappa["kappa2_by_mass"]]
        + list(record["8x4"]["induced_state"])
        + [coupling[tag]["coefficient"] for tag in TAGS]
        + [MARGIN_CONSTANT, HOLO_COEFFICIENT]
    )
    exact = all(no_float(value) for value in scalars)

    return Facts(
        main_head=main_head,
        authority=authority,
        convention=convention,
        freezing=tuple((tag, freezing[tag]) for tag in TAGS),
        composite=tuple((tag, composite[tag]) for tag in TAGS[:2]),
        coupling=(tuple((tag, coupling[tag]) for tag in TAGS), wiring),
        margin=(tuple((tag, margin[tag]) for tag in TAGS), kappa, census, wall,
                exchange, tuple((tag, mass_inertia[tag]) for tag in TAGS[:2])),
        record=tuple((tag, record[tag]) for tag in TAGS),
        shape=shape,
        deep=deep,
        exact_no_float=exact,
        scope=scope_certificate(raw_note()),
    )


